<script>
(() => {
 const form = document.querySelector('[data-answer-form]');
 if (!form) return;
 const update = () => { const choice = form.querySelector('[name="answerer"]:checked')?.value; form.querySelectorAll('[data-answer-fields]').forEach(section => { const active = section.dataset.answerFields === choice; section.hidden = !active; section.querySelectorAll('input,select').forEach(input => { input.disabled = !active; input.required = active; }); }); };
 form.addEventListener('change', update); update();
 document.querySelectorAll('a[href^="#phone-"]').forEach(link => link.addEventListener('click', () => { const details = document.getElementById(link.getAttribute('href').slice(1)); if(details) details.open = true; }));
})();
</script>
